class Solution {
public:
    string baseNeg2(int n) {
        if (n == 0) return "0";
        string result;
        while (n != 0) {
            int bit = n & 1;
            result += char('0' + bit);
            n = (n - bit) / -2;
        }
        reverse(result.begin(), result.end());
        return result;
    }
};
